WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessionized AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, account_id, merchant, is_flagged, session_no FROM sessionized;
